    MANIFEST,
    '''    "MIGRATION_PACKAGE_ROOT",\n    "PreparedGitProvenanceAuthorization",\n''',
    '''    "MIGRATION_PACKAGE_ROOT",\n    "GitAuthorizationProfile",\n    "ORDINARY_AUTHORIZATION_PROFILE",\n    "STANDARD_FOUR_HOUR_AUTHORIZATION_PROFILE",\n    "PreparedGitProvenanceAuthorization",\n''',
